/* 3mm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"

/* Tunable blocking factors.
 * These tile sizes are chosen to improve cache locality.
 * They can be overridden at compile time, e.g. -DTILE_I=64.
 */
#ifndef TILE_I
# define TILE_I 32
#endif

#ifndef TILE_J
# define TILE_J 32
#endif

#ifndef TILE_K
# define TILE_K 32
#endif

#ifndef TILE_L
# define TILE_L 32
#endif

#ifndef TILE_M
# define TILE_M 32
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Explicit cache blocking (tiling) over all dimensions.
   - Loop reordering so innermost loops iterate over contiguous memory
     (columns), improving data locality and enabling vectorization.
   - Scalar replacement: hoist A/C/E elements into scalars and reuse
     them across the innermost loops instead of reloading.
   - Coarse-grain OpenMP parallelization over outer tiles (rows) for
     each GEMM phase (E, F, G). If compiled without -fopenmp, the
     pragmas are ignored and the code remains correct.
 */
static
void kernel_3mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k, l, m;

#pragma scop
  /* ------------------------------------------------------ */
  /* Phase 1: E := A * B                                    */
  /*        E is NI x NJ, A is NI x NK, B is NK x NJ        */
  /* ------------------------------------------------------ */

  /* Initialize E to zero (one clean pass over memory). */
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      E[i][j] = SCALAR_VAL(0.0);

  /* Blocked matrix multiplication with i-k-j ordering.
   * Loop nest: I (tile over i), K (tile over k), J (tile over j),
   *            then i, k, j inside tiles.
   * Innermost loop is over j, which is contiguous in memory for both
   * E[i][*] and B[k][*].
   */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(i,j,k)
#endif
  for (int ii = 0; ii < _PB_NI; ii += TILE_I)
  {
    int i_end = ii + TILE_I;
    if (i_end > _PB_NI) i_end = _PB_NI;

    for (int kk = 0; kk < _PB_NK; kk += TILE_K)
    {
      int k_end = kk + TILE_K;
      if (k_end > _PB_NK) k_end = _PB_NK;

      for (int jj = 0; jj < _PB_NJ; jj += TILE_J)
      {
        int j_end = jj + TILE_J;
        if (j_end > _PB_NJ) j_end = _PB_NJ;

        const int width = j_end - jj;

        for (i = ii; i < i_end; ++i)
        {
          /* Pointer to the beginning of the current E tile row. */
          DATA_TYPE *restrict E_row = &E[i][jj];

          for (k = kk; k < k_end; ++k)
          {
            const DATA_TYPE a_ik = A[i][k];
            const DATA_TYPE *restrict B_row = &B[k][jj];

            /* Update a block of E[i][j] for this a_ik. */
            for (j = 0; j < width; ++j)
            {
              E_row[j] += a_ik * B_row[j];
            }
          }
        }
      }
    }
  }

  /* ------------------------------------------------------ */
  /* Phase 2: F := C * D                                    */
  /*        F is NJ x NL, C is NJ x NM, D is NM x NL        */
  /* ------------------------------------------------------ */

  /* Initialize F to zero. */
  for (j = 0; j < _PB_NJ; j++)
    for (l = 0; l < _PB_NL; l++)
      F[j][l] = SCALAR_VAL(0.0);

  /* Blocked matrix multiplication with j-m-l ordering.
   * Loop nest: J (tile over j), M (tile over m), L (tile over l),
   *            then j, m, l inside tiles.
   * Innermost loop is over l, contiguous for F[j][*] and D[m][*].
   */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(j,l,m)
#endif
  for (int jj = 0; jj < _PB_NJ; jj += TILE_J)
  {
    int j_end = jj + TILE_J;
    if (j_end > _PB_NJ) j_end = _PB_NJ;

    for (int mm = 0; mm < _PB_NM; mm += TILE_M)
    {
      int m_end = mm + TILE_M;
      if (m_end > _PB_NM) m_end = _PB_NM;

      for (int ll = 0; ll < _PB_NL; ll += TILE_L)
      {
        int l_end = ll + TILE_L;
        if (l_end > _PB_NL) l_end = _PB_NL;

        const int width = l_end - ll;

        for (j = jj; j < j_end; ++j)
        {
          DATA_TYPE *restrict F_row = &F[j][ll];

          for (m = mm; m < m_end; ++m)
          {
            const DATA_TYPE c_jm = C[j][m];
            const DATA_TYPE *restrict D_row = &D[m][ll];

            /* Update a block of F[j][l] for this c_jm. */
            for (l = 0; l < width; ++l)
            {
              F_row[l] += c_jm * D_row[l];
            }
          }
        }
      }
    }
  }

  /* ------------------------------------------------------ */
  /* Phase 3: G := E * F                                    */
  /*        G is NI x NL, E is NI x NJ, F is NJ x NL        */
  /* ------------------------------------------------------ */

  /* Initialize G to zero. */
  for (i = 0; i < _PB_NI; i++)
    for (l = 0; l < _PB_NL; l++)
      G[i][l] = SCALAR_VAL(0.0);

  /* Blocked matrix multiplication with i-j-l ordering.
   * Loop nest: I (tile over i), J (tile over j), L (tile over l),
   *            then i, j, l inside tiles.
   * Innermost loop is over l, contiguous for G[i][*] and F[j][*].
   */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(i,j,l)
#endif
  for (int ii = 0; ii < _PB_NI; ii += TILE_I)
  {
    int i_end = ii + TILE_I;
    if (i_end > _PB_NI) i_end = _PB_NI;

    for (int jj = 0; jj < _PB_NJ; jj += TILE_J)
    {
      int j_end = jj + TILE_J;
      if (j_end > _PB_NJ) j_end = _PB_NJ;

      for (int ll = 0; ll < _PB_NL; ll += TILE_L)
      {
        int l_end = ll + TILE_L;
        if (l_end > _PB_NL) l_end = _PB_NL;

        const int width = l_end - ll;

        for (i = ii; i < i_end; ++i)
        {
          DATA_TYPE *restrict G_row = &G[i][ll];

          for (j = jj; j < j_end; ++j)
          {
            const DATA_TYPE e_ij = E[i][j];
            const DATA_TYPE *restrict F_row = &F[j][ll];

            /* Accumulate G[i][*] using the current E[i][j] and row of F. */
            for (l = 0; l < width; ++l)
            {
              G_row[l] += e_ij * F_row[l];
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
