    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;
  int l, m;
  int ii, jj, kk, ll, mm;

  /* Small, static tile sizes chosen so that one tile of A/B/E, C/D/F, or
     E/F/G fits comfortably in L1 cache on a modern x64 core.  They are
     independent of the problem sizes and handle all remainders explicitly. */
  const int tile_i = 32;
  const int tile_j = 32;
  const int tile_k = 32;
  const int tile_l = 32;
  const int tile_m = 32;

#pragma scop
  /* --------------------------------------------------------------------
   * Phase 1: E := A * B
   *   E is NI x NJ
   *   A is NI x NK (row-major)
   *   B is NK x NJ (row-major)
   *
   * Baseline:
   *   for i
   *     for j
   *       E[i][j] = 0;
   *       for k
   *         E[i][j] += A[i][k] * B[k][j];
   *
   * Optimized:
   *   - First zero E.
   *   - Then use a tiled i-k-j ordering:
   *       for ii (tiles of i)
   *         for kk (tiles of k)
   *           for jj (tiles of j)
   *             for i in ii-tile
   *               for k in kk-tile
   *                 aik = A[i][k];                // scalar
   *                 for j in jj-tile (contiguous)
   *                   E[i][j] += aik * B[k][j];
   *
   *   This gives:
   *     - unit-stride (contiguous) access in j for both E and B,
   *     - good cache locality on small A/B/E tiles,
   *     - reduced loads of A[i][k] via scalar reuse.
   * ------------------------------------------------------------------ */

  /* Initialize E to zero. */
  for (i = 0; i < _PB_NI; ++i)
    for (j = 0; j < _PB_NJ; ++j)
      E[i][j] = SCALAR_VAL(0.0);

  /* Blocked matrix multiplication for E = A * B. */
  for (ii = 0; ii < _PB_NI; ii += tile_i)
  {
    int i_end = ii + tile_i;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (kk = 0; kk < _PB_NK; kk += tile_k)
    {
      int k_end = kk + tile_k;
      if (k_end > _PB_NK)
        k_end = _PB_NK;

      for (jj = 0; jj < _PB_NJ; jj += tile_j)
      {
        int j_end = jj + tile_j;
        if (j_end > _PB_NJ)
          j_end = _PB_NJ;

        const int width = j_end - jj;

        for (i = ii; i < i_end; ++i)
        {
          for (k = kk; k < k_end; ++k)
          {
            DATA_TYPE a_ik = A[i][k];
            DATA_TYPE *E_row = &E[i][jj];
            const DATA_TYPE *B_row = &B[k][jj];

            /* Inner loop over j is unit-stride for both E and B, which
               is friendly to hardware prefetching and auto-vectorization. */
            for (int t = 0; t < width; ++t)
              E_row[t] += a_ik * B_row[t];
          }
        }
      }
    }
  }

  /* --------------------------------------------------------------------
   * Phase 2: F := C * D
   *   F is NJ x NL
   *   C is NJ x NM (row-major)
   *   D is NM x NL (row-major)
   *
   * Baseline:
   *   for j
   *     for l
   *       F[j][l] = 0;
   *       for m
   *         F[j][l] += C[j][m] * D[m][l];
   *
   * Optimized:
   *   - First zero F.
   *   - Then use tiled j-m-l ordering:
   *       for jj (tiles of j)
   *         for mm (tiles of m)
   *           for ll (tiles of l)
   *             for j in jj-tile
   *               for m in mm-tile
   *                 c_jm = C[j][m];              // scalar
   *                 for l in ll-tile (contiguous)
   *                   F[j][l] += c_jm * D[m][l];
   *
   *   As in E, the innermost loop runs over the contiguous column index l,
   *   giving unit-stride access for both F and D and good cache reuse.
   * ------------------------------------------------------------------ */

  /* Initialize F to zero. */
  for (j = 0; j < _PB_NJ; ++j)
    for (l = 0; l < _PB_NL; ++l)
      F[j][l] = SCALAR_VAL(0.0);

  /* Blocked matrix multiplication for F = C * D. */
  for (jj = 0; jj < _PB_NJ; jj += tile_j)
  {
    int j_end = jj + tile_j;
    if (j_end > _PB_NJ)
      j_end = _PB_NJ;

    for (mm = 0; mm < _PB_NM; mm += tile_m)
    {
      int m_end = mm + tile_m;
      if (m_end > _PB_NM)
        m_end = _PB_NM;

      for (ll = 0; ll < _PB_NL; ll += tile_l)
      {
        int l_end = ll + tile_l;
        if (l_end > _PB_NL)
          l_end = _PB_NL;

        const int width = l_end - ll;

        for (j = jj; j < j_end; ++j)
        {
          for (m = mm; m < m_end; ++m)
          {
            DATA_TYPE c_jm = C[j][m];
            DATA_TYPE *F_row = &F[j][ll];
            const DATA_TYPE *D_row = &D[m][ll];

            for (int t = 0; t < width; ++t)
              F_row[t] += c_jm * D_row[t];
          }
        }
      }
    }
  }

  /* --------------------------------------------------------------------
   * Phase 3: G := E * F
   *   G is NI x NL
   *   E is NI x NJ (row-major)
   *   F is NJ x NL (row-major)
   *
   * Baseline:
   *   for i
   *     for l
   *       G[i][l] = 0;
   *       for j
   *         G[i][l] += E[i][j] * F[j][l];
   *
   * Optimized:
   *   - First zero G.
   *   - Then use tiled i-j-l ordering:
   *       for ii (tiles of i)
   *         for jj (tiles of j)
   *           for ll (tiles of l)
   *             for i in ii-tile
   *               for j in jj-tile
   *                 e_ij = E[i][j];              // scalar
   *                 for l in ll-tile (contiguous)
   *                   G[i][l] += e_ij * F[j][l];
   *
   *   This keeps the innermost loop over l, the contiguous dimension of
   *   both F and G, while reusing E[i][j] across that block of columns.
   * ------------------------------------------------------------------ */

  /* Initialize G to zero. */
  for (i = 0; i < _PB_NI; ++i)
    for (l = 0; l < _PB_NL; ++l)
      G[i][l] = SCALAR_VAL(0.0);

  /* Blocked matrix multiplication for G = E * F. */
  for (ii = 0; ii < _PB_NI; ii += tile_i)
  {
    int i_end = ii + tile_i;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (jj = 0; jj < _PB_NJ; jj += tile_j)
    {
      int j_end = jj + tile_j;
      if (j_end > _PB_NJ)
        j_end = _PB_NJ;

      for (ll = 0; ll < _PB_NL; ll += tile_l)
      {
        int l_end = ll + tile_l;
        if (l_end > _PB_NL)
          l_end = _PB_NL;

        const int width = l_end - ll;

        for (i = ii; i < i_end; ++i)
        {
          DATA_TYPE *G_row = &G[i][ll];

          for (j = jj; j < j_end; ++j)
          {
            DATA_TYPE e_ij = E[i][j];
            const DATA_TYPE *F_row = &F[j][ll];

            for (int t = 0; t < width; ++t)
              G_row[t] += e_ij * F_row[t];
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_3mm (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(E),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(F),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D),
	      POLYBENCH_ARRAY(G));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(G)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(E);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(F);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);
  POLYBENCH_FREE_ARRAY(G);

  return 0;
}
