  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k, l, m;
  /* Tile indices for the three GEMMs. */
  int I_E, J_E, K_E;
  int J_F, L_F, M_F;
  int I_G, J_G, L_G;

  /* Tunable tile sizes.
     These values are chosen for typical L1/L2 cache sizes on x86-64.
     They safely handle arbitrary problem sizes via min() logic below. */
  const int tile_i_e = 32;
  const int tile_j_e = 32;
  const int tile_k_e = 32;

  const int tile_j_f = 32;
  const int tile_l_f = 32;
  const int tile_m_f = 32;

  const int tile_i_g = 32;
  const int tile_j_g = 32;
  const int tile_l_g = 32;

#pragma scop
  /* --------------------------------------------------------------
   * First GEMM:  E := A * B
   *   (NI x NK) * (NK x NJ) -> (NI x NJ)
   *
   * Optimized loop order and blocking:
   *   - Initialize E once up-front.
   *   - Block over i, k, j.
   *   - Within each tile, use ordering i -> k -> j so that:
   *       * the innermost loop iterates over j (unit stride in memory),
   *       * A[i][k] is hoisted into a scalar for reuse across j,
   *       * rows of B[k][*] and E[i][*] are both accessed contiguously.
   * -------------------------------------------------------------- */

  /* Initialize E to 0.0 (one write per element). */
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      E[i][j] = SCALAR_VAL(0.0);

  for (I_E = 0; I_E < _PB_NI; I_E += tile_i_e) {
    int i_max = I_E + tile_i_e;
    if (i_max > _PB_NI)
      i_max = _PB_NI;

    for (K_E = 0; K_E < _PB_NK; K_E += tile_k_e) {
      int k_max = K_E + tile_k_e;
      if (k_max > _PB_NK)
        k_max = _PB_NK;

      for (J_E = 0; J_E < _PB_NJ; J_E += tile_j_e) {
        int j_max = J_E + tile_j_e;
        if (j_max > _PB_NJ)
          j_max = _PB_NJ;

        for (i = I_E; i < i_max; ++i) {
          /* Row pointers improve locality and expose unit-stride
             accesses on the innermost loop to the compiler. */
          DATA_TYPE *restrict Ei = E[i];
          const DATA_TYPE *restrict Ai = A[i];

          for (k = K_E; k < k_max; ++k) {
            const DATA_TYPE aik = Ai[k];
            const DATA_TYPE *restrict Bk = B[k];

            for (j = J_E; j < j_max; ++j) {
              Ei[j] += aik * Bk[j];
            }
          }
        }
      }
    }
  }

  /* --------------------------------------------------------------
   * Second GEMM:  F := C * D
   *   (NJ x NM) * (NM x NL) -> (NJ x NL)
   *
   * Optimized loop order and blocking:
   *   - Initialize F once up-front.
   *   - Block over j, m, l.
   *   - Within each tile, use ordering j -> m -> l so that:
   *       * the innermost loop iterates over l (unit stride),
   *       * C[j][m] is hoisted into a scalar across l,
   *       * rows of D[m][*] and F[j][*] are accessed contiguously.
   * -------------------------------------------------------------- */

  /* Initialize F to 0.0. */
  for (j = 0; j < _PB_NJ; j++)
    for (l = 0; l < _PB_NL; l++)
      F[j][l] = SCALAR_VAL(0.0);

  for (J_F = 0; J_F < _PB_NJ; J_F += tile_j_f) {
    int j_max = J_F + tile_j_f;
    if (j_max > _PB_NJ)
      j_max = _PB_NJ;

    for (M_F = 0; M_F < _PB_NM; M_F += tile_m_f) {
      int m_max = M_F + tile_m_f;
      if (m_max > _PB_NM)
        m_max = _PB_NM;

      for (L_F = 0; L_F < _PB_NL; L_F += tile_l_f) {
        int l_max = L_F + tile_l_f;
        if (l_max > _PB_NL)
          l_max = _PB_NL;

        for (j = J_F; j < j_max; ++j) {
          DATA_TYPE *restrict Fj = F[j];
          const DATA_TYPE *restrict Cj = C[j];

          for (m = M_F; m < m_max; ++m) {
            const DATA_TYPE cjm = Cj[m];
            const DATA_TYPE *restrict Dm = D[m];

            for (l = L_F; l < l_max; ++l) {
              Fj[l] += cjm * Dm[l];
            }
          }
        }
      }
    }
  }

  /* --------------------------------------------------------------
   * Third GEMM:  G := E * F
   *   (NI x NJ) * (NJ x NL) -> (NI x NL)
   *
   * Optimized loop order and blocking:
   *   - Initialize G once up-front.
   *   - Block over i, j(reduction), l.
   *   - Within each tile, use ordering i -> j -> l so that:
   *       * the innermost loop iterates over l (unit stride),
   *       * E[i][j] is hoisted into a scalar across l,
   *       * rows of F[j][*] and G[i][*] are accessed contiguously.
   * -------------------------------------------------------------- */

  /* Initialize G to 0.0. */
  for (i = 0; i < _PB_NI; i++)
    for (l = 0; l < _PB_NL; l++)
      G[i][l] = SCALAR_VAL(0.0);

  for (I_G = 0; I_G < _PB_NI; I_G += tile_i_g) {
    int i_max = I_G + tile_i_g;
    if (i_max > _PB_NI)
      i_max = _PB_NI;

    for (J_G = 0; J_G < _PB_NJ; J_G += tile_j_g) {
      int j_max = J_G + tile_j_g;
      if (j_max > _PB_NJ)
        j_max = _PB_NJ;

      for (L_G = 0; L_G < _PB_NL; L_G += tile_l_g) {
        int l_max = L_G + tile_l_g;
        if (l_max > _PB_NL)
          l_max = _PB_NL;

        for (i = I_G; i < i_max; ++i) {
          DATA_TYPE *restrict Gi = G[i];
          const DATA_TYPE *restrict Ei = E[i];

          for (j = J_G; j < j_max; ++j) {
            const DATA_TYPE eij = Ei[j];
            const DATA_TYPE *restrict Fj = F[j];

            for (l = L_G; l < l_max; ++l) {
              Gi[l] += eij * Fj[l];
            }
          }
        }
