#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (following the high-level models in 3mm-03/05):
   - Separate initialization of E, F, G (clear once, then accumulate).
   - Cache blocking (tiling) for all three GEMMs.
   - Loop reordering so the innermost loop is over the contiguous
     dimension (j or l), enabling efficient vectorization.
   - Scalar replacement: values like A[i,k], C[j,m], E[i,j] are hoisted
     into registers and reused across the innermost loop.
   - Use of restrict-qualified local aliases to help the compiler
     with alias analysis and auto-vectorization.

   The mathematical results are identical to the original code up to
   floating-point reordering effects.
*/
static
void kernel_3mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

  /* Create restrict-qualified aliases with explicit row-stride.
     This gives the compiler clearer information about aliasing and
     the actual leading dimensions, which helps vectorization. */
  DATA_TYPE (*restrict E_)[nj] = E;
  DATA_TYPE (*restrict A_)[nk] = A;
  DATA_TYPE (*restrict B_)[nj] = B;
  DATA_TYPE (*restrict F_)[nl] = F;
  DATA_TYPE (*restrict C_)[nm] = C;
  DATA_TYPE (*restrict D_)[nl] = D;
  DATA_TYPE (*restrict G_)[nl] = G;

  /* Tunable tile sizes. These are chosen conservatively; for a given
     machine they can be adjusted to better match the cache hierarchy. */
  const int TI_E = 32;
  const int TJ_E = 32;
  const int TK_E = 32;

  const int TJ_F = 32;
  const int TL_F = 32;
  const int TM_F = 32;

  const int TI_G = 32;
  const int TL_G = 32;
  const int TJ_G = 32;

#pragma scop
  /*------------------------------------------------------------------
    Phase 0: Initialize temporaries and result
    ------------------------------------------------------------------*/
  /* E := 0 */
  for (i = 0; i < _PB_NI; ++i)
    for (j = 0; j < _PB_NJ; ++j)
      E_[i][j] = SCALAR_VAL(0.0);

  /* F := 0 */
  for (i = 0; i < _PB_NJ; ++i)
    for (j = 0; j < _PB_NL; ++j)
      F_[i][j] = SCALAR_VAL(0.0);

  /* G := 0 */
  for (i = 0; i < _PB_NI; ++i)
    for (j = 0; j < _PB_NL; ++j)
      G_[i][j] = SCALAR_VAL(0.0);

  /*------------------------------------------------------------------
    Phase 1: E := A * B
      Original:
        for i
          for j
            E[i][j] = 0;
            for k
              E[i][j] += A[i][k] * B[k][j];

      Optimized structure (tiled, i-k-j ordering inside tiles):
        for I over tiles of i
          for K over tiles of k
            for J over tiles of j
              for i in I-tile
                for k in K-tile
                  a_ik = A[i][k];
                  for j in J-tile    // j contiguous
                    E[i][j] += a_ik * B[k][j];

      This keeps:
        - A[i][k] in a scalar across a block of columns j,
        - B[k][j] and E[i][j] accessed with unit stride in j.
    ------------------------------------------------------------------*/
  for (int I = 0; I < _PB_NI; I += TI_E) {
    int i_end = I + TI_E;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (int K = 0; K < _PB_NK; K += TK_E) {
      int k_end = K + TK_E;
      if (k_end > _PB_NK)
        k_end = _PB_NK;

      for (int J = 0; J < _PB_NJ; J += TJ_E) {
        int j_end = J + TJ_E;
        if (j_end > _PB_NJ)
          j_end = _PB_NJ;
        int len_j = j_end - J;

        for (i = I; i < i_end; ++i) {
          DATA_TYPE *restrict E_row = &E_[i][J];

          for (k = K; k < k_end; ++k) {
            const DATA_TYPE a_ik = A_[i][k];
            const DATA_TYPE *restrict B_row = &B_[k][J];

            /* Innermost loop over contiguous columns j. */
            for (int jj = 0; jj < len_j; ++jj)
              E_row[jj] += a_ik * B_row[jj];
          }
        }
      }
    }
  }

  /*------------------------------------------------------------------
    Phase 2: F := C * D
      Original:
        for j
          for l
            F[j][l] = 0;
            for m
              F[j][l] += C[j][m] * D[m][l];

      Optimized structure (tiled, j-m-l ordering inside tiles):
        for J over tiles of j
          for M over tiles of m
            for L over tiles of l
              for j in J-tile
                for m in M-tile
                  c_jm = C[j][m];
                  for l in L-tile    // l contiguous
                    F[j][l] += c_jm * D[m][l];

      This keeps:
        - C[j][m] in a scalar across a block of columns l,
        - D[m][l] and F[j][l] accessed with unit stride in l.
    ------------------------------------------------------------------*/
  for (int J = 0; J < _PB_NJ; J += TJ_F) {
    int j_end = J + TJ_F;
    if (j_end > _PB_NJ)
      j_end = _PB_NJ;

    for (int M = 0; M < _PB_NM; M += TM_F) {
      int m_end = M + TM_F;
      if (m_end > _PB_NM)
        m_end = _PB_NM;

      for (int L = 0; L < _PB_NL; L += TL_F) {
        int l_end = L + TL_F;
        if (l_end > _PB_NL)
          l_end = _PB_NL;
        int len_l = l_end - L;

        for (j = J; j < j_end; ++j) {
          DATA_TYPE *restrict F_row = &F_[j][L];

          for (int m = M; m < m_end; ++m) {
            const DATA_TYPE c_jm = C_[j][m];
            const DATA_TYPE *restrict D_row = &D_[m][L];

            /* Innermost loop over contiguous columns l. */
            for (int ll = 0; ll < len_l; ++ll)
              F_row[ll] += c_jm * D_row[ll];
          }
        }
      }
    }
  }

  /*------------------------------------------------------------------
    Phase 3: G := E * F
      Original:
        for i
          for l
            G[i][l] = 0;
            for j
              G[i][l] += E[i][j] * F[j][l];

      Optimized structure (tiled, i-j-l ordering inside tiles):
        for I over tiles of i
          for J over tiles of j
            for L over tiles of l
              for i in I-tile
                for j in J-tile
                  e_ij = E[i][j];
                  for l in L-tile    // l contiguous
                    G[i][l] += e_ij * F[j][l];

      This keeps:
        - E[i][j] in a scalar while updating a block of columns l,
        - F[j][l] and G[i][l] accessed with unit stride in l.
    ------------------------------------------------------------------*/
  for (int I = 0; I < _PB_NI; I += TI_G) {
    int i_end = I + TI_G;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (int J = 0; J < _PB_NJ; J += TJ_G) {
      int j_end = J + TJ_G;
      if (j_end > _PB_NJ)
        j_end = _PB_NJ;

      for (int L = 0; L < _PB_NL; L += TL_G) {
        int l_end = L + TL_G;
        if (l_end > _PB_NL)
          l_end = _PB_NL;
        int len_l = l_end - L;

        for (i = I; i < i_end; ++i) {
          DATA_TYPE *restrict G_row = &G_[i][L];

          for (j = J; j < j_end; ++j) {
            const DATA_TYPE e_ij = E_[i][j];
            const DATA_TYPE *restrict F_row = &F_[j][L];

            /* Innermost loop over contiguous columns l. */
            for (int ll = 0; ll < len_l; ++ll)
              G_row[ll] += e_ij * F_row[ll];
          }
        }
      }
    }
  }
#pragma endscop

}


